public int getPivotRow(int pivotColumn) {
    int minRatioRow = -1;
    double minRatio = Double.MAX_VALUE;

    for (int i = 0; i < numRows; i++) {
        if (matrix[i][pivotColumn] > 0) {
            double ratio = matrix[i][numCols - 1] / matrix[i][pivotColumn];
            if (ratio < minRatio) {
                minRatio = ratio;
                minRatioRow = i;
            }
        }
    }

    return minRatioRow;
}

